<section x-show="tab==='audio'" x-cloak @vsg-editor-tab.window="if($event.detail.tab!=='audio')$el.querySelectorAll('audio').forEach(a=>a.pause())" x-data="storyAudio(@js(route('audio.index',$story)))" class="space-y-6">
<header><h2 class="font-serif text-2xl">Audio</h2><p class="mt-1 text-sm text-stone-500">Find sounds or generate your own, then assign them in Scenes.</p></header>
@include('studio.audio-pending')
<p x-show="error" x-text="error" role="alert" class="text-sm text-red-600"></p>
<div class="grid items-start gap-5 lg:grid-cols-2">
<div class="min-w-0 rounded-xl border border-stone-200 p-4 dark:border-stone-700">
<div role="tablist" aria-label="Find or generate audio" class="mb-4 flex gap-4 border-b border-stone-200 dark:border-stone-700">
<button type="button" role="tab" id="audio-search-tab" aria-controls="audio-search-panel" :aria-selected="audioMode==='search'" @click="audioMode='search'" class="border-b-2 pb-2 text-sm" :class="audioMode==='search'?'border-current font-semibold':'border-transparent text-stone-500'">Search</button>
<button type="button" role="tab" id="audio-generate-tab" aria-controls="audio-generate-panel" :aria-selected="audioMode==='generate'" @click="audioMode='generate';$el.closest('section').querySelectorAll('audio').forEach(a=>a.pause())" class="border-b-2 pb-2 text-sm" :class="audioMode==='generate'?'border-current font-semibold':'border-transparent text-stone-500'">Generate</button>
</div>
<section id="audio-search-panel" role="tabpanel" aria-labelledby="audio-search-tab" x-show="audioMode==='search'" class="min-w-0 space-y-3"><h3 class="text-xs font-semibold">Freesound</h3>
<form @submit.prevent="search(1)" class="flex flex-wrap items-end gap-2"><label class="field min-w-0 flex-1 basis-40">Search<input x-model="query" placeholder="Rain, creaking door, footsteps..." maxlength="200" required></label><label class="field w-28">Max seconds<input type="number" min="0.1" max="3600" step="0.1" x-model="maxDuration" placeholder="Any" :disabled="searching" @change="results=[];page=1;hasMore=false;if(query.trim())search(1)"></label><button class="btn-primary" :disabled="searching" x-text="searching?'Searching…':'Search'"></button></form>
<div class="flex flex-wrap gap-2"><template x-for="q in searches" :key="q"><button type="button" class="text-xs underline" @click="query=q;search(1)" x-text="q"></button></template></div>
<p class="text-xs text-stone-500">High-quality MP3 previews. Creator and license credits are saved with each sound.</p>
<div class="max-h-[60vh] space-y-2 overflow-y-auto"><template x-for="s in results" :key="s.id"><article class="min-w-0 rounded-lg border border-stone-200 p-3 dark:border-stone-700 space-y-2 text-xs">
<div class="flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-1"><a :href="s.source_url" target="_blank" rel="noopener noreferrer" class="break-words text-xs font-semibold underline" x-text="s.name"></a><span class="text-xs text-stone-500" x-text="s.creator"></span><a :href="s.license" :title="s.license" target="_blank" rel="noopener noreferrer" class="min-w-0 max-w-40 truncate text-xs underline" x-text="s.license"></a><span class="ml-auto shrink-0 text-xs" x-text="Number(s.duration).toFixed(1)+'s'"></span></div>
<div class="flex min-w-0 items-center gap-2"><audio controls preload="none" :src="s.preview_url" class="h-10 min-w-0 flex-1" @play="$el.closest('section').querySelectorAll('audio').forEach(a=>{if(a!==$el)a.pause()})"></audio><button type="button" class="btn-secondary shrink-0 !px-3 !py-2 !text-xs" :disabled="busy || added(s.id)" @click="add(s.id)" :aria-label="'Add '+s.name+' to project'" x-text="added(s.id)?'Added':'Add'"></button></div>
</article></template></div>
<div x-show="results.length" class="flex items-center justify-between text-sm"><button type="button" class="underline" :disabled="searching || page===1" @click="search(page-1)">Previous</button><span x-text="'Page '+page+' · '+count+' results'"></span><button type="button" class="underline" :disabled="searching || !hasMore" @click="search(page+1)">Next</button></div>
</section>
<section id="audio-generate-panel" role="tabpanel" aria-labelledby="audio-generate-tab" x-show="audioMode==='generate'" x-cloak class="min-w-0 space-y-3"><label class="field">Model<select x-model="model" @change="seconds=Math.min(seconds,model==='cassetteai/sound-effects-generator'?30:47)"><option value="fal-ai/stable-audio">Stable Audio</option><option value="cassetteai/sound-effects-generator">CassetteAI sound effects</option></select></label><form @submit.prevent="generate()" class="space-y-3"><label class="field">Name<input x-model="name" required maxlength="160" placeholder="A heavy wooden door opening"></label><label class="field">Sound prompt<textarea x-model="prompt" required maxlength="3000" rows="4" placeholder="Describe the sound, atmosphere, and timing..."></textarea></label><label class="field">Duration (seconds)<input type="number" min="1" :max="model==='cassetteai/sound-effects-generator'?30:47" x-model="seconds" required></label><button class="btn-primary" :disabled="generating" x-text="generating?'Submitting…':'Generate sound'"></button></form>
<div class="max-h-72 overflow-y-auto space-y-2"><template x-for="j in jobs.filter(j=>!editableJob(j))" :key="j.id"><details class="rounded-lg border border-stone-200 p-3 dark:border-stone-700"><summary class="cursor-pointer text-sm"><span x-text="j.name"></span> · <span :class="['queued','running','submitting'].includes(j.status)?'animate-pulse':''" x-text="j.status"></span><span x-show="j.queue_position!==null" x-text="' · Queue position '+j.queue_position"></span></summary><p class="mt-2 whitespace-pre-wrap text-sm" x-text="j.prompt"></p><p x-show="j.error" class="mt-2 text-sm text-red-600" x-text="j.error"></p><template x-for="(log,i) in j.logs||[]" :key="i"><p class="text-xs" x-text="log.message"></p></template></details></template></div></section>
</div>
<section class="min-w-0 rounded-xl border border-stone-200 p-4 dark:border-stone-700 space-y-3"><div class="flex flex-wrap items-center gap-2"><h3 class="font-serif text-xl">Project sounds</h3><select class="audio-library-select" aria-label="Filter project sounds" :value="categoryFilter" @change="categoryFilter=$event.target.value;$el.closest('section').querySelectorAll('audio').forEach(a=>a.pause())"><option value="">All categories</option><template x-for="(name,key) in categories" :key="key"><option :value="key" x-text="name"></option></template></select><button type="button" class="text-xs underline" @click="categoriesOpen=!categoriesOpen">Edit categories</button></div>
<div x-show="categoriesOpen" class="space-y-2 rounded border p-3"><template x-for="(name,key) in categories" :key="key"><input :aria-label="'Category '+name" :value="name" maxlength="80" @change="categories[key]=$event.target.value;saveCategories()"></template><div class="flex gap-2"><input aria-label="New category" x-model="newCategory" maxlength="80" placeholder="New category"><button type="button" class="btn-secondary" @click="addCategory()">Add</button></div></div><p x-show="!filteredSounds.length" class="text-sm text-stone-500" x-text="sounds.length?'No sounds in this category.':'No sounds yet.'"></p><div class="max-h-[75vh] space-y-2 overflow-y-auto"><template x-for="s in filteredSounds" :key="s.id"><article class="rounded-xl border border-stone-200 p-4 dark:border-stone-700 space-y-2"><div class="flex flex-wrap items-baseline gap-x-2 gap-y-1 text-xs"><h4 class="break-words text-xs font-semibold" x-text="s.name"></h4><span x-show="s.creator" class="text-xs text-stone-500" x-text="s.creator"></span><a x-show="s.license" :href="s.license" :title="s.license" target="_blank" rel="noopener noreferrer" class="max-w-40 truncate text-xs underline">License</a><a x-show="s.source_url" :href="s.source_url" target="_blank" rel="noopener noreferrer" class="text-xs underline">Source</a><span class="ml-auto text-xs" x-text="s.provider==='freesound'?'Freesound':'AI generated'"></span></div><div class="flex items-center gap-3"><select class="audio-library-select" aria-label="Sound category" :value="s.category||'effects'" @change="categorize(s,$event.target.value)"><template x-for="(name,key) in categories" :key="key"><option :value="key" :selected="key===(s.category||'effects')" x-text="name"></option></template></select><button type="button" class="text-xs text-red-700 underline dark:text-red-400" @click="deleteSound(s)">Delete audio</button></div><audio controls preload="none" :src="s.url" class="w-full"></audio><p x-show="s.prompt" class="text-xs whitespace-pre-wrap" x-text="s.prompt"></p></article></template></div></section>
</div>
</section>
